package kyo.proto.kernel.internal

import kyo.proto.Arrow
import kyo.proto.kernel.Effect

/** The regions an eval has open, outermost first.
  *
  * One entry per installed region: the handler that answers for it, the state the loop threads through it, the context to restore when it
  * ends, and the continuation that follows it. Holding a region here rather than in a Java frame is what lets regions nest to any depth: the
  * eval stays one self-recursive loop, and an open region costs an entry instead of a frame.
  *
  * Mutable, and scoped to a single `Eval.apply`, which is the only thing that holds one. A nested eval builds its own, so it sees none of the
  * outer eval's regions, and nothing the eval hands out points here.
  *
  * The arrays hold every region's values, so their element types are the erasure and each read is asserted at the type the matching push
  * established. The entries are strictly heterogeneous, which is why the assertion cannot be carried in a signature.
  */
final private[kyo] class Stack:

    // shared and empty until the first region is installed. Every eval builds a stack and most never install
    // anything, so allocating four arrays in the constructor put 224 B/op on evals with no region in them at
    // all, measured on `evalFixedOverhead`. The first `push` finds no room and grows into real arrays.
    private var handlers      = Stack.noHandlers
    private var states        = Stack.noStates
    private var contexts      = Stack.noContexts
    private var continuations = Stack.noContinuations
    private var size          = 0

    def isEmpty: Boolean = size == 0

    /** Installs a region. Typed, because the pushing site knows all five: the state has to be the one this
      * handler threads, and the continuation has to start where this handler's result ends. Those are the two
      * ways an entry can be built wrong, and both are checked here rather than asserted on the way out.
      */
    def push[E <: Effect, A, B, S, State](
        handler: Handler[E, A, B, S, State],
        state: State,
        ctx: Context,
        cont: Arrow[B, Any, S]
    ): Unit =
        if size == handlers.length then grow()
        handlers(size) = handler
        states(size) = state
        contexts(size) = ctx
        continuations(size) = cont
        size += 1
    end push

    /** Drops the innermost region. The slots it used keep their references until a deeper push overwrites
      * them or the eval ends, so a stack that reached depth n holds up to n entries' worth for the rest
      * of that eval. Clearing them is the alternative and costs four stores on the path every region
      * exit takes; neither has been measured, and the retention is bounded by the eval's peak depth.
      */
    def pop(): Unit = size -= 1

    // the innermost region, which is the only one an eval step can be inside. Every call site reaches these
    // behind its own `isEmpty` test, so an empty stack has no reads rather than a defined answer for them
    def handler: Handler[?, ?, ?, ?, ?] = handlers(size - 1)
    def state: Any                      = states(size - 1)
    def state_=(value: Any): Unit       = states(size - 1) = value
    def ctx: Context                    = contexts(size - 1)
    def cont: Arrow[?, ?, ?]            = continuations(size - 1)

    // out of line: growth is cold, and the push it serves is on the region path. The first call finds the
    // shared empty arrays and lands on the floor rather than doubling nothing
    private def grow(): Unit =
        val capacity           = if size == 0 then 8 else size * 2
        val grownHandlers      = new Array[Handler[?, ?, ?, ?, ?]](capacity)
        val grownStates        = new Array[Any](capacity)
        val grownContexts      = new Array[Context](capacity)
        val grownContinuations = new Array[Arrow[?, ?, ?]](capacity)
        Array.copy(handlers, 0, grownHandlers, 0, size)
        Array.copy(states, 0, grownStates, 0, size)
        Array.copy(contexts, 0, grownContexts, 0, size)
        Array.copy(continuations, 0, grownContinuations, 0, size)
        handlers = grownHandlers
        states = grownStates
        contexts = grownContexts
        continuations = grownContinuations
    end grow
end Stack

private[kyo] object Stack:
    // one set for the whole process. They are never written, because a write needs room and having none is
    // what sends the first push through `grow`
    private val noHandlers      = new Array[Handler[?, ?, ?, ?, ?]](0)
    private val noStates        = new Array[Any](0)
    private val noContexts      = new Array[Context](0)
    private val noContinuations = new Array[Arrow[?, ?, ?]](0)
end Stack

// the regions this eval installs. A nested eval builds its own, so it answers for the
// regions it installed and for none of the enclosing ones
val stack = Stack()

// the depth guard bounds strict recursion within one eval, so the budget is this eval's and
// not whatever the thread had left. Inheriting a spent one is a fixed point rather than a
// slow path: every application defers, the settled arm applies the deferral, and its
// continuation is the application that just deferred.
//
// Restored in the finally below so a nested eval hands the enclosing one back what it had,
// its part-spent depth and its armed bit included. That restore has no test: a nested eval's
// own exits return most of what it spent, so the enclosing eval survives losing it, and the
// armed bit is unobservable while nothing in the proto arms. It is kept because discarding a
// caller's state is wrong whether or not this tree can currently see it, and because the
// reference kernel's eval does the same at the same place
val slot  = Safepoint.get()
val saved = Safepoint.save(slot)

// `loop` runs the machine to its answer, which is why it returns the eval's result rather
// than the composition of its arguments: once a region's continuation waits on the stack,
// "v with contA then contB applied" stops describing what the call produces
@tailrec def loop[T, B, C, S2](v: T < S2, contA: Arrow[T, B, S2], contB: Arrow[B, C, S2], ctx: Context): A < S =

case kyo: Kyo.Handle[EX, AX, Y, T, S2, VX] @unchecked =>
    // a context binding resolves at installation: it derives from whatever the
    // enclosing scope binds for its tag, and a re-installed region derives again
    // from wherever it stands
    var st0 = kyo.state
    val bound = kyo.handler match
        case h: Handler.HandlerContext[VX, CX, AX, Y, S2] @unchecked =>
            val hc: Handler.HandlerContext[VX, CX, AX, Y, S2] = h
            st0 = hc.resolve(Maybe.when(ctx.contains(hc.tag))(ctx[VX, CX](hc.tag)))
            ctx.update(hc.tag, st0)
        case _ => ctx
    Debugger.onRegionEnter(kyo.handler, st0)
    // the region is installed rather than entered: what follows it waits on the stack,
    // so its interior is evaluated by this same loop instead of by a nested one
    stack.push(kyo.handler, st0, ctx, kyo.cont.chain(contA.chain(contB)))
    loop(kyo.value, Arrow.id, Arrow.id, bound)

// The regions a throw unwinds, innermost first, ending in the value the region that recovered
// resumes with. A region that declines is popped and the failure keeps unwinding through the
// ones outside it; with none left the eval fails as its caller's does. A recover that fails
// itself is the failure those outer regions see, which is what the per-region guards did by
// nesting.
//
// The region that recovers is left on the stack, and the resume below pops it. That is what
// lets this return one value rather than the value and the context to resume it at, which
// would be a pair allocated on the path `Abort` runs through.
@tailrec def recovered(ex: Throwable): A < S =
    if stack.isEmpty then throw ex
    else
        val handler = stack.handler.asInstanceOf[Handler[EX, AX, Y, Any, VX]]
        val state   = stack.state.asInstanceOf[VX]
        val outcome =
            try handler.recover(state, ex)
            catch
                case ex2 if NonFatal(ex2) =>
                    stack.pop()
                    return recovered(ex2)
        outcome match
            case Present(r) =>
                Debugger.onRecover(handler, ex)
                Debugger.onRegionExit(handler, r)
                r.chain(stack.cont.asInstanceOf[Arrow[Y, A, S]])
            case Absent =>
                stack.pop()
                recovered(ex)
        end match

// The eval and its guard. Recovering resumes here and reading a default that no region
// answered resumes here, and both are self tail calls, so the eval that removed the frame per
// open region reintroduces none per recovered region or per default answered.
@tailrec def guarded(curr: A < S, ctx: Context): A < S =
    val res =
        try loop(curr, Arrow.id, Arrow.id, ctx)
        catch
            case failure if NonFatal(failure) =>
                // the budget counts strict applications still on the Java stack, and a throw
                // that reaches here left every one of them without its matching exit. The eval
                // is back at its own frame, so the true depth is zero and the counter says
                // otherwise; left uncorrected the leak accumulates over an extent's recoveries
                // until the budget drains, and a drained budget is a fixed point rather than a
                // slow path
                Safepoint.reset(slot)
                val resumed = recovered(failure)
                // the region that recovered is still on the stack, holding the context to
                // resume at; taking it here is what keeps the unwind allocation free
                val outer = stack.ctx
                stack.pop()
                return guarded(resumed, outer)
    res match
        case suspend: Kyo.SuspendContextDefault[VX, CX, A, S] @unchecked =>
            val nv = suspend.update(suspend.default)
            Debugger.onContextDefault(suspend, nv)
            val k = suspend.cont
            guarded(k.head(nv, k.tail), Context.empty)
        case susp: Kyo.Suspend[?, ?, ?] =>
            // an operation with no region left to answer it. Rejecting here keeps the failure
            // at the operation that caused it: handed back, it is a node typed as a value, and
            // the cast that discovers it fires arbitrarily far away. The arm below this one is
            // the reason this is not the loop's business: a context read whose default nobody
            // answered leaves the loop the same way and is answered, not rejected
            bug(s"unhandled suspension: $susp")
        case res => res
    end match
end guarded

try guarded(v, Context.empty)
finally Safepoint.restore(slot, saved)

    // stackless and shared: the test is about the eval's stack, and filling a trace ten thousand
    // times measures the JVM's exception construction instead
    private object Boom extends RuntimeException("boom", null, false, false)

    // A context read rebinds "the updated value for the rest of that region's extent", and an
    // answered operation is inside that extent. The public surface cannot show this: every
    // ContextEffect.suspend carries an identity update, so the node is built here directly.
    "a context update outlives an operation answered after it" in {
        sealed trait Count extends kyo.proto.kernel.ContextEffect[Int]
        def bump: Int < Count =
            new Kyo.SuspendContext[Int, Count, Int, Count]:
                def tag            = Tag[Count]
                def update(v: Int) = v + 1
                def cont           = Arrow.id
        // bound at 10: the first read rebinds 11, the Ask region answers, the second read sees 11
        // and rebinds 12. Resuming an answered operation with the context the region was installed
        // with instead would lose the first update and give 11
        val body: Int < (Count & Ask) = bump.map(_ => ask.map(_ => bump))
        val r: Int < Count            = answerAsk(0)(body)
        assert(eval(kyo.proto.kernel.ContextEffect.handle(Tag[Count], 10)(r)) == 12)
    }

    // the eval holds no frame per open region, and it must hold none per recovered one either: a
    // recovery that resumed by evaluating the rest of the eval from inside its own guard would make
    // this grow with the number of throws rather than stay flat
    "regions that fail and recover in sequence cost no stack" in {
        def recovering(to: Int): Int < Any =
            val h = new Handler.HandlerCont[Const[Unit], Const[Int], Ask, Int, Int, Any]:
                def tag                                          = Tag[Ask]
                override def recover(state: Unit, ex: Throwable) = Maybe(to)
                def done(state: Unit, v: Int)                    = v
                def run[X, C, S2](input: Unit, cont: Arrow[Int, Int, Ask], k: Arrow[Int, C, S2]): C < (Ask & S2) =
                    k(cont(0, Arrow.id), Arrow.id)
            val body: Int < Ask = ask.map(_ => (throw Boom): Int)
            Kyo.handle[Ask, Int, Int, Any, Unit](body, h, ())
        end recovering
        def go(i: Int): Int < Any =
            if i == 0 then 0
            else recovering(i).map(_ => go(i - 1))
        assert(eval(go(10000)) == 0)
    }

    // The budget counts the strict applications standing on the Java stack, and a throw unwinds them
    // without their matching exits. The eval's guard repairs that where it catches, but a foreign
    // crossing carries its own recover, and a throw recovered there left the count short by every
    // application it unwound. A drained count is a fixed point rather than a slow path, so enough of
    // these livelock; the count is sampled directly here, which fails while the scenario still ends.
    "a region recovering across a foreign crossing leaves the budget where it found it" in {
        val samples = collection.mutable.ListBuffer.empty[Safepoint.State]
        def sample(): Unit =
            val slot = Safepoint.get()
            // `save` installs a fresh budget as it reads, so reading it back is a save/restore pair
            val d = Safepoint.save(slot)
            Safepoint.restore(slot, d)
            samples += d
        end sample

        // the Say region is foreign to the Ask its body suspends, so answering that Ask resumes
        // through the rebuilt node, and the throw that follows lands in the crossing's own recover
        def crossing(to: Int): Int < Ask =
            val h = new Handler.HandlerCont[Const[String], Const[Unit], Say, Int, Int, Ask]:
                def tag                                          = Tag[Say]
                override def recover(state: Unit, ex: Throwable) = Maybe(to)
                def done(state: Unit, v: Int)                    = v
                def run[X, C, S2](input: String, cont: Arrow[Unit, Int, Say & Ask], k: Arrow[Int, C, S2]): C < (Say & Ask & S2) =
                    k(cont((), Arrow.id), Arrow.id)
            val body: Int < (Say & Ask) = ask.map(_ => (throw Boom): Int)
            Kyo.handle[Say, Int, Int, Ask, Unit](body, h, ())
        end crossing

        // fewer cycles than the budget has entries, so a leaking eval still terminates and the
        // samples say so, rather than the suite hanging on the fixed point
        def go(i: Int): Int < Ask =
            if i == 0 then (0: Int < Ask)
            else
                crossing(i).map { _ =>
                    sample()
                    go(i - 1)
                }
        assert(eval(answerAsk(0)(go(100))) == 0)
        assert(samples.size == 100)
        // `equals` rather than `==`: `State` is opaque and carries no `CanEqual`, and a cast to its
        // underlying Int would be a new cast for a test's convenience
        assert(samples.forall(_.equals(samples.head)))
    }

    // `recover` is consulted with its region still installed, and one that fails itself is the
    // failure the regions outside it then see. The baseline got that free from nested tries; the
    // unwind is its own control flow now, and has been rewritten twice, so it is pinned rather than
    // stated. No test threw from a `recover` before this one.
    "a recover that fails itself is the failure the enclosing region sees" in {
        object Inner extends RuntimeException("inner", null, false, false)
        var seen = Maybe.empty[Throwable]

        val innerHandler = new Handler.HandlerCont[Const[String], Const[Unit], Say, Int, Int, Ask]:
            def tag                                          = Tag[Say]
            override def recover(state: Unit, ex: Throwable) = throw Inner
            def done(state: Unit, v: Int)                    = v
            def run[X, C, S2](input: String, cont: Arrow[Unit, Int, Say & Ask], k: Arrow[Int, C, S2]): C < (Say & Ask & S2) =
                k(cont((), Arrow.id), Arrow.id)

        val outerHandler = new Handler.HandlerCont[Const[Unit], Const[Int], Ask, Int, Int, Any]:
            def tag = Tag[Ask]
            override def recover(state: Unit, ex: Throwable) =
                seen = Maybe(ex)
                Maybe(7)
            def done(state: Unit, v: Int) = v
            def run[X, C, S2](input: Unit, cont: Arrow[Int, Int, Ask], k: Arrow[Int, C, S2]): C < (Ask & S2) =
                k(cont(0, Arrow.id), Arrow.id)

        // deferred, so the throw lands while the loop is inside the region rather than while the
        // computation is being built
        val body: Int < (Say & Ask) = Effect.defer((throw Boom): Int < (Say & Ask))
        val inner: Int < Ask        = Kyo.handle[Say, Int, Int, Ask, Unit](body, innerHandler, ())
        val outer: Int < Any        = Kyo.handle[Ask, Int, Int, Any, Unit](inner, outerHandler, ())
        assert(eval(outer) == 7)
        // the second failure, not the one the inner region declined by throwing
        assert(seen.exists(_ eq Inner))
    }

end EvalTest
